//! Every outside host the app can reach, `network.jadpo_record` (areas 11
//! and 18, chunk A8): a view of the network report that `jadpo check`
//! keeps at the root beside `api/`, so a new host is a diff in the pull
//! request and has a before side to judge an acceptance against.
//!
//! One entry per connection, saying what it is reached for and each host
//! as the report gives it: an address as written, the setting an address
//! is read from (`config.ledger_address`), or the image of a service Jadpo
//! runs.
//!
//! ```text
//! // Generated by Jadpo from the hosts the app can reach; update it with `jadpo records update`, never by hand.
//! record network 1
//!
//! connection couriers
//!     for AcmeCouriers.v1
//!     host https://api.acme-couriers.example
//!     host https://sandbox.acme-couriers.example
//! ```

use std::collections::BTreeMap;

use jadpo_db::record::{self as format, Entry};
use jadpo_db::{Db, Project};

/// The record's file, at the root.
pub const PATH: &str = format::NETWORK_FILE;

/// The record's text: `Some(None)` when the app reaches no host, `None`
/// while its connections have errors.
#[salsa::tracked(returns(ref))]
pub fn record_text(db: &dyn Db, project: Project) -> Option<Option<String>> {
    if project.layout(db) != jadpo_db::Layout::Project
        || !crate::connections::connection_problems(db, project).is_empty()
        || !crate::config::connection_problems(db, project).is_empty()
    {
        return None;
    }
    let mut by_connection: BTreeMap<String, (String, Vec<String>)> = BTreeMap::new();
    for row in crate::connections::hosts(db, project, false) {
        let host = if let Some(address) = &row.address {
            address.clone()
        } else if let Some(setting) = &row.setting {
            format!("config.{setting}")
        } else if let Some(image) = &row.image {
            format!("service {image}")
        } else {
            continue;
        };
        let reached_for = reached_for(&row);
        let entry = by_connection
            .entry(row.connection.clone())
            .or_insert_with(|| (reached_for, Vec::new()));
        entry.1.push(host);
    }
    if by_connection.is_empty() {
        return Some(None);
    }
    let entries: Vec<Entry> = by_connection
        .into_iter()
        .map(|(connection, (reached_for, mut hosts))| {
            hosts.sort();
            hosts.dedup();
            let mut entry = Entry::new(format!("connection {connection}"));
            entry.push(format!("for {reached_for}"));
            for host in hosts {
                entry.push(format!("host {host}"));
            }
            entry
        })
        .collect();
    Some(Some(format::write(
        &format::NETWORK,
        format::NETWORK_FROM,
        &entries,
    )))
}

/// What a host is reached for, in one word or a package's name: the
/// report's column without its wording.
fn reached_for(row: &crate::connections::Row) -> String {
    let said = row.reached_for.as_str();
    if row.connection == "external_token" {
        return "identity".to_string();
    }
    for word in ["database", "cache", "email", "ai"] {
        if said == word || said.starts_with(&format!("{word},")) {
            return word.to_string();
        }
    }
    said.trim_matches('`').to_string()
}
